     1→import { useState, useCallback, useEffect } from "react";
     2→import { data } from "react-router";
     3→import type {
     4→  ActionFunctionArgs,
     5→  HeadersFunction,
     6→  LoaderFunctionArgs,
     7→} from "react-router";
     8→import { useLoaderData, useNavigate, useSubmit } from "react-router";
     9→import {
    10→  Page,
    11→  Layout,
    12→  Card,
    13→  Text,
    14→  InlineStack,
    15→  BlockStack,
    16→  Badge,
    17→  Button,
    18→  Box,
    19→  Divider,
    20→  IndexTable,
    21→  Modal,
    22→  EmptyState,
    23→  useIndexResourceState,
    24→  ButtonGroup,
    25→  SkeletonPage,
    26→  SkeletonBodyText,
    27→} from "@shopify/polaris";
    28→import { useAppBridge } from "@shopify/app-bridge-react";
    29→import { authenticate } from "../shopify.server";
    30→import { boundary } from "@shopify/shopify-app-react-router/server";
    31→import { getQuizzes, deleteQuiz } from "../services/quiz.server";
    32→import db from "../db.server";
    33→
    34→// --- Types ---
    35→
    36→type BadgeTone = "success" | "attention" | "warning" | undefined;
    37→
    38→// --- Status helpers ---
    39→
    40→const statusToneMap: Record<string, BadgeTone> = {
    41→  active: "success",
    42→  draft: "attention",
    43→  paused: "warning",
    44→  archived: undefined,
    45→};
    46→
    47→function formatStatus(status: string): string {
    48→  return status.charAt(0).toUpperCase() + status.slice(1);
    49→}
    50→
    51→function formatQuizType(type: string): string {
    52→  return type
    53→    .split("-")
    54→    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    55→    .join(" ");
    56→}
    57→
    58→// --- Templates (static) ---
    59→
    60→const templates = [
    61→  {
    62→    id: "skincare",
    63→    name: "Skincare Finder",
    64→    emoji: "\uD83E\uDDF4",
    65→    category: "Beauty, Wellness",
    66→    questions: 5,
    67→    types: "Single choice, Image choice, Multiple select, Slider, Email capture",
    68→    badge: "Popular" as const,
    69→  },
    70→  {
    71→    id: "supplement",
    72→    name: "Supplement Advisor",
    73→    emoji: "\uD83D\uDC8A",
    74→    category: "Health, Fitness",
    75→    questions: 4,
    76→    types: "Single choice, Yes/No, Multiple select, Email capture",
    77→    badge: "New" as const,
    78→  },
    79→  {
    80→    id: "style",
    81→    name: "Style Finder",
    82→    emoji: "\uD83D\uDC57",
    83→    category: "Apparel, Fashion",
    84→    questions: 4,
    85→    types: "Image choice, Single choice, Dropdown, Email capture",
    86→    badge: null,
    87→  },
    88→  {
    89→    id: "haircare",
    90→    name: "Hair Care Match",
    91→    emoji: "\uD83D\uDC87",
    92→    category: "Hair, Beauty",
    93→    questions: 4,
    94→    types: "Single choice, Dropdown, Slider, Email capture",
    95→    badge: null,
    96→  },
    97→  {
    98→    id: "fitness",
    99→    name: "Fitness Advisor",
   100→    emoji: "\uD83C\uDFCB\uFE0F",
   101→    category: "Sports, Health",
   102→    questions: 5,
   103→    types: "Single choice, Multiple select, Slider, Yes/No, Email capture",
   104→    badge: null,
   105→  },
   106→  {
   107→    id: "blank",
   108→    name: "Start from blank",
   109→    emoji: "\u2795",
   110→    category: "Custom",
   111→    questions: 0,
   112→    types: "Manual",
   113→    badge: null,
   114→  },
   115→];
   116→
   117→const progressSteps = [
   118→  "Reading product catalogue...",
   119→  "Generating questions & answers...",
   120→  "Mapping products to answers...",
   121→  "Finalising your quiz...",
   122→];
   123→
   124→// --- Loader ---
   125→
   126→export const loader = async ({ request }: LoaderFunctionArgs) => {
   127→  const { session } = await authenticate.admin(request);
   128→  try {
   129→    const quizzes = await getQuizzes(session.shop);
   130→    return { quizzes };
   131→  } catch (error) {
   132→    throw data({ error: "Failed to load quizzes" }, { status: 500 });
   133→  }
   134→};
   135→
   136→// --- Action ---
   137→
   138→export const action = async ({ request }: ActionFunctionArgs) => {
   139→  const { session } = await authenticate.admin(request);
   140→  const formData = await request.formData();
   141→  const intent = formData.get("intent") as string;
   142→  const id = formData.get("id") as string;
   143→
   144→  try {
   145→    if (intent === "archive") {
   146→      const quiz = await db.quiz.findFirst({
   147→        where: { id, shop: session.shop },
   148→      });
   149→      if (!quiz) {
   150→        return data({ error: "Quiz not found or access denied" }, { status: 404 });
   151→      }
   152→      await db.quiz.update({
   153→        where: { id },
   154→        data: { status: "archived" },
   155→      });
   156→      return { success: true, message: "Quiz archived" };
   157→    }
   158→
   159→    if (intent === "delete") {
   160→      await deleteQuiz(id, session.shop);
   161→      return { success: true, message: "Quiz deleted" };
   162→    }
   163→
   164→    return data({ error: "Unknown intent" }, { status: 400 });
   165→  } catch (error) {
   166→    return data({ error: "Action failed" }, { status: 500 });
   167→  }
   168→};
   169→
   170→// --- Hydrate Fallback (skeleton) ---
   171→
   172→export function HydrateFallback() {
   173→  return (
   174→    <SkeletonPage title="My Quizzes" primaryAction>
   175→      <BlockStack gap="600">
   176→        <Card>
   177→          <SkeletonBodyText lines={8} />
   178→        </Card>
   179→      </BlockStack>
   180→    </SkeletonPage>
   181→  );
   182→}
   183→
   184→// --- Components ---
   185→
   186→function TemplateCard({
   187→  template,
   188→  onSelect,
   189→}: {
   190→  template: (typeof templates)[0];
   191→  onSelect: (id: string) => void;
   192→}) {
   193→  const badgeTone =
   194→    template.badge === "Popular"
   195→      ? "success"
   196→      : template.badge === "New"
   197→        ? "info"
   198→        : undefined;
   199→
   200→  return (
   201→    <div
   202→      style={{
   203→        cursor: "pointer",
   204→        border: "1px solid var(--p-color-border)",
   205→        borderRadius: "var(--p-border-radius-300)",
   206→        padding: "16px",
   207→        transition: "box-shadow 0.15s ease",
   208→        height: "100%",
   209→      }}
   210→      onClick={() => onSelect(template.id)}
   211→      onMouseEnter={(e) => {
   212→        (e.currentTarget as HTMLElement).style.boxShadow =
   213→          "0 0 0 2px var(--p-color-border-emphasis)";
   214→      }}
   215→      onMouseLeave={(e) => {
   216→        (e.currentTarget as HTMLElement).style.boxShadow = "none";
   217→      }}
   218→      role="button"
   219→      tabIndex={0}
   220→      onKeyDown={(e) => {
   221→        if (e.key === "Enter" || e.key === " ") {
   222→          e.preventDefault();
   223→          onSelect(template.id);
   224→        }
   225→      }}
   226→    >
   227→      <BlockStack gap="300">
   228→        <InlineStack align="space-between" blockAlign="start">
   229→          <Text as="span" variant="headingXl">
   230→            {template.emoji}
   231→          </Text>
   232→          {template.badge && (
   233→            <Badge tone={badgeTone}>{template.badge}</Badge>
   234→          )}
   235→        </InlineStack>
   236→        <BlockStack gap="100">
   237→          <Text as="p" variant="headingSm" fontWeight="semibold">
   238→            {template.name}
   239→          </Text>
   240→          <InlineStack gap="100">
   241→            {template.category.split(", ").map((cat) => (
   242→              <Badge key={cat} tone="info">
   243→                {cat}
   244→              </Badge>
   245→            ))}
   246→          </InlineStack>
   247→        </BlockStack>
   248→        <Text as="p" variant="bodySm" tone="subdued">
   249→          {template.questions === 0
   250→            ? "No pre-built questions"
   251→            : `${template.questions} questions`}
   252→        </Text>
   253→      </BlockStack>
   254→    </div>
   255→  );
   256→}
   257→
   258→function AIGenerationOverlay({
   259→  onComplete,
   260→}: {
   261→  onComplete: () => void;
   262→}) {
   263→  const [currentStep, setCurrentStep] = useState(0);
   264→  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
   265→
   266→  useEffect(() => {
   267→    const timers: ReturnType<typeof setTimeout>[] = [];
   268→
   269→    progressSteps.forEach((_, index) => {
   270→      const timer = setTimeout(() => {
   271→        setCurrentStep(index);
   272→        if (index > 0) {
   273→          setCompletedSteps((prev) => [...prev, index - 1]);
   274→        }
   275→      }, index * 750);
   276→      timers.push(timer);
   277→    });
   278→
   279→    // Mark last step complete and navigate
   280→    const finalTimer = setTimeout(() => {
   281→      setCompletedSteps((prev) => [...prev, progressSteps.length - 1]);
   282→    }, progressSteps.length * 750);
   283→    timers.push(finalTimer);
   284→
   285→    const navTimer = setTimeout(() => {
   286→      onComplete();
   287→    }, progressSteps.length * 750 + 500);
   288→    timers.push(navTimer);
   289→
   290→    return () => timers.forEach(clearTimeout);
   291→  }, [onComplete]);
   292→
   293→  return (
   294→    <div
   295→      style={{
   296→        position: "fixed",
   297→        inset: 0,
   298→        zIndex: 9999,
   299→        background: "rgba(255, 255, 255, 0.97)",
   300→        display: "flex",
   301→        alignItems: "center",
   302→        justifyContent: "center",
   303→      }}
   304→    >
   305→      <div style={{ textAlign: "center", maxWidth: 420 }}>
   306→        <div
   307→          style={{
   308→            width: 64,
   309→            height: 64,
   310→            margin: "0 auto 24px",
   311→            border: "4px solid var(--p-color-border)",
   312→            borderTopColor: "var(--p-color-border-emphasis)",
   313→            borderRadius: "50%",
   314→            animation: "quizsnap-spin 0.8s linear infinite",
   315→          }}
   316→        />
   317→        <style>
   318→          {`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}
   319→        </style>
   320→        <BlockStack gap="200">
   321→          <Text as="p" variant="headingLg" fontWeight="bold">
   322→            Building your quiz with AI...
   323→          </Text>
   324→          <Text as="p" variant="bodySm" tone="subdued">
   325→            This usually takes a few seconds
   326→          </Text>
   327→        </BlockStack>
   328→        <div style={{ marginTop: 32, textAlign: "left" }}>
   329→          <BlockStack gap="300">
   330→            {progressSteps.map((step, index) => {
   331→              const isCompleted = completedSteps.includes(index);
   332→              const isCurrent = currentStep === index && !isCompleted;
   333→              return (
   334→                <InlineStack key={index} gap="300" blockAlign="center">
   335→                  <div
   336→                    style={{
   337→                      width: 24,
   338→                      height: 24,
   339→                      borderRadius: "50%",
   340→                      display: "flex",
   341→                      alignItems: "center",
   342→                      justifyContent: "center",
   343→                      fontSize: 14,
   344→                      background: isCompleted
   345→                        ? "var(--p-color-bg-fill-success)"
   346→                        : isCurrent
   347→                          ? "var(--p-color-bg-fill-emphasis)"
   348→                          : "var(--p-color-bg-surface-secondary)",
   349→                      color: isCompleted || isCurrent ? "#fff" : "var(--p-color-text-subdued)",
   350→                      flexShrink: 0,
   351→                    }}
   352→                  >
   353→                    {isCompleted ? "\u2713" : index + 1}
   354→                  </div>
   355→                  <Text
   356→                    as="p"
   357→                    variant="bodyMd"
   358→                    tone={isCompleted ? "success" : isCurrent ? undefined : "subdued"}
   359→                    fontWeight={isCurrent ? "semibold" : "regular"}
   360→                  >
   361→                    {step}
   362→                  </Text>
   363→                </InlineStack>
   364→              );
   365→            })}
   366→          </BlockStack>
   367→        </div>
   368→      </div>
   369→    </div>
   370→  );
   371→}
   372→
   373→// --- Main Page ---
   374→
   375→export default function MyQuizzes() {
   376→  const { quizzes } = useLoaderData<typeof loader>();
   377→  const navigate = useNavigate();
   378→  const submit = useSubmit();
   379→  const shopify = useAppBridge();
   380→
   381→  const [modalOpen, setModalOpen] = useState(false);
   382→  const [showAIOverlay, setShowAIOverlay] = useState(false);
   383→  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
   384→
   385→  const showEmptyState = quizzes.length === 0;
   386→
   387→  const handleOpenModal = useCallback(() => {
   388→    setModalOpen(true);
   389→  }, []);
   390→
   391→  const handleCloseModal = useCallback(() => {
   392→    setModalOpen(false);
   393→  }, []);
   394→
   395→  const handleSelectTemplate = useCallback(
   396→    (templateId: string) => {
   397→      setSelectedTemplate(templateId);
   398→      setModalOpen(false);
   399→
   400→      if (templateId === "blank") {
   401→        navigate("/app/quizzes/new");
   402→      } else {
   403→        setShowAIOverlay(true);
   404→      }
   405→    },
   406→    [navigate],
   407→  );
   408→
   409→  const handleAIComplete = useCallback(() => {
   410→    setShowAIOverlay(false);
   411→    shopify.toast.show("Quiz created successfully!");
   412→    navigate(`/app/quizzes/new?template=${selectedTemplate}`);
   413→  }, [navigate, selectedTemplate, shopify]);
   414→
   415→  const handleEditQuiz = useCallback(
   416→    (id: string) => {
   417→      navigate(`/app/quizzes/${id}`);
   418→    },
   419→    [navigate],
   420→  );
   421→
   422→  const handlePreviewQuiz = useCallback(
   423→    (id: string) => {
   424→      navigate(`/app/quizzes/${id}/preview`);
   425→    },
   426→    [navigate],
   427→  );
   428→
   429→  const handleArchiveQuiz = useCallback(
   430→    (id: string) => {
   431→      const formData = new FormData();
   432→      formData.append("intent", "archive");
   433→      formData.append("id", id);
   434→      submit(formData, { method: "POST" });
   435→      shopify.toast.show("Quiz archived");
   436→    },
   437→    [submit, shopify],
   438→  );
   439→
   440→  const resourceName = { singular: "quiz", plural: "quizzes" };
   441→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
   442→    useIndexResourceState(quizzes);
   443→
   444→  const rowMarkup = quizzes.map(
   445→    (
   446→      quiz: {
   447→        id: string;
   448→        title: string;
   449→        type: string;
   450→        status: string;
   451→        completions: number;
   452→        updatedAt: Date | string;
   453→        _count: { questions: number; responses: number };
   454→      },
   455→      index: number,
   456→    ) => (
   457→      <IndexTable.Row
   458→        id={quiz.id}
   459→        key={quiz.id}
   460→        selected={selectedResources.includes(quiz.id)}
   461→        position={index}
   462→      >
   463→        <IndexTable.Cell>
   464→          <InlineStack gap="300" blockAlign="center">
   465→            <Text as="span" variant="headingMd">
   466→              {"📊"}
   467→            </Text>
   468→            <BlockStack gap="050">
   469→              <Text as="span" variant="bodyMd" fontWeight="semibold">
   470→                {quiz.title}
   471→              </Text>
   472→              <Text as="span" variant="bodySm" tone="subdued">
   473→                {formatQuizType(quiz.type)}
   474→              </Text>
   475→            </BlockStack>
   476→          </InlineStack>
   477→        </IndexTable.Cell>
   478→        <IndexTable.Cell>
   479→          <Badge tone={statusToneMap[quiz.status]}>
   480→            {formatStatus(quiz.status)}
   481→          </Badge>
   482→        </IndexTable.Cell>
   483→        <IndexTable.Cell>
   484→          <Text as="span" variant="bodyMd" alignment="end">
   485→            {quiz._count.questions}
   486→          </Text>
   487→        </IndexTable.Cell>
   488→        <IndexTable.Cell>
   489→          <Text as="span" variant="bodyMd" alignment="end">
   490→            {quiz.completions.toLocaleString()}
   491→          </Text>
   492→        </IndexTable.Cell>
   493→        <IndexTable.Cell>
   494→          <Text as="span" variant="bodyMd" alignment="end">
   495→            {"—"}
   496→          </Text>
   497→        </IndexTable.Cell>
   498→        <IndexTable.Cell>
   499→          <Text as="span" variant="bodyMd" alignment="end">
   500→            {"—"}
   501→          </Text>
   502→        </IndexTable.Cell>
   503→        <IndexTable.Cell>
   504→          <Text as="span" variant="bodySm" tone="subdued">
   505→            {new Date(quiz.updatedAt).toLocaleDateString("en-US", {
   506→              month: "short",
   507→              day: "numeric",
   508→              year: "numeric",
   509→            })}
   510→          </Text>
   511→        </IndexTable.Cell>
   512→        <IndexTable.Cell>
   513→          <ButtonGroup>
   514→            <Button size="slim" onClick={() => handleEditQuiz(quiz.id)}>
   515→              Edit
   516→            </Button>
   517→            <Button
   518→              size="slim"
   519→              variant="plain"
   520→              onClick={() => handlePreviewQuiz(quiz.id)}
   521→            >
   522→              Preview
   523→            </Button>
   524→            <Button
   525→              size="slim"
   526→              variant="plain"
   527→              tone="critical"
   528→              onClick={() => handleArchiveQuiz(quiz.id)}
   529→            >
   530→              Archive
   531→            </Button>
   532→          </ButtonGroup>
   533→        </IndexTable.Cell>
   534→      </IndexTable.Row>
   535→    ),
   536→  );
   537→
   538→  return (
   539→    <>
   540→      {showAIOverlay && <AIGenerationOverlay onComplete={handleAIComplete} />}
   541→
   542→      <Page
   543→        title="My Quizzes"
   544→        primaryAction={{
   545→          content: "+ Create quiz",
   546→          onAction: handleOpenModal,
   547→        }}
   548→      >
   549→        <BlockStack gap="600">
   550→          {showEmptyState ? (
   551→            <Card>
   552→              <EmptyState
   553→                heading="Create your first quiz"
   554→                action={{
   555→                  content: "Create quiz",
   556→                  onAction: handleOpenModal,
   557→                }}
   558→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
   559→              >
   560→                <p>
   561→                  Build product recommendation quizzes that help your customers
   562→                  find the perfect product and boost your sales.
   563→                </p>
   564→              </EmptyState>
   565→            </Card>
   566→          ) : (
   567→            <Layout>
   568→              <Layout.Section>
   569→                <Card padding="0">
   570→                  <BlockStack>
   571→                    <Box padding="400">
   572→                      <InlineStack align="space-between" blockAlign="center">
   573→                        <Text as="h2" variant="headingMd">
   574→                          All Quizzes
   575→                        </Text>
   576→                        <Text as="p" variant="bodySm" tone="subdued">
   577→                          {quizzes.length} {quizzes.length === 1 ? "quiz" : "quizzes"}
   578→                        </Text>
   579→                      </InlineStack>
   580→                    </Box>
   581→                    <IndexTable
   582→                      resourceName={resourceName}
   583→                      itemCount={quizzes.length}
   584→                      selectedItemsCount={
   585→                        allResourcesSelected
   586→                          ? "All"
   587→                          : selectedResources.length
   588→                      }
   589→                      onSelectionChange={handleSelectionChange}
   590→                      headings={[
   591→                        { title: "Quiz" },
   592→                        { title: "Status" },
   593→                        { title: "Questions", alignment: "end" },
   594→                        { title: "Completions", alignment: "end" },
   595→                        { title: "Conv. Rate", alignment: "end" },
   596→                        { title: "Revenue", alignment: "end" },
   597→                        { title: "Updated" },
   598→                        { title: "Actions" },
   599→                      ]}
   600→                    >
   601→                      {rowMarkup}
   602→                    </IndexTable>
   603→                  </BlockStack>
   604→                </Card>
   605→              </Layout.Section>
   606→            </Layout>
   607→          )}
   608→        </BlockStack>
   609→      </Page>
   610→
   611→      <Modal open={modalOpen} onClose={handleCloseModal} title="Choose a template">
   612→        <Box padding="400">
   613→          <BlockStack gap="400">
   614→            <Text as="h2" variant="headingLg" fontWeight="bold">
   615→              Choose a template
   616→            </Text>
   617→            <Text as="p" variant="bodyMd" tone="subdued">
   618→              Pick a pre-built quiz template or start from scratch
   619→            </Text>
   620→            <Divider />
   621→            <div
   622→              style={{
   623→                display: "grid",
   624→                gridTemplateColumns: "repeat(3, 1fr)",
   625→                gap: "16px",
   626→              }}
   627→            >
   628→              {templates.map((template) => (
   629→                <TemplateCard
   630→                  key={template.id}
   631→                  template={template}
   632→                  onSelect={handleSelectTemplate}
   633→                />
   634→              ))}
   635→            </div>
   636→          </BlockStack>
   637→        </Box>
   638→      </Modal>
   639→    </>
   640→  );
   641→}
   642→
   643→export const headers: HeadersFunction = (headersArgs) => {
   644→  return boundary.headers(headersArgs);
   645→};
