   104→
   105→export async function loader({ request }: LoaderFunctionArgs) {
   106→  const { session } = await authenticate.admin(request);
   107→
   108→  try {
   109→    const [customTemplates, globalTemplates] = await Promise.all([
   110→      db.quizTemplate.findMany({
   111→        where: { shop: session.shop, isGlobal: false },
   112→        orderBy: { createdAt: "desc" },
   113→      }),
   114→      db.quizTemplate.findMany({
   115→        where: { isGlobal: true },
   116→        orderBy: { usageCount: "desc" },
   117→      }),
   118→    ]);
   119→
   120→    return { customTemplates, globalTemplates };
   121→  } catch (error) {
   122→    console.error("Templates loader error:", error);
   123→    throw data({ error: "Failed to load templates" }, { status: 500 });
   124→  }
   125→}
   126→
   127→// ─── Action ───────────────────────────────────────────────────────────────────
   128→
   129→export async function action({ request }: ActionFunctionArgs) {
   130→  const { session } = await authenticate.admin(request);
   131→  const formData = await request.formData();
   132→  const intent = formData.get("intent") as string;
   133→
   134→  if (intent === "use-template") {
   135→    const templateId = formData.get("templateId") as string;
   136→
   137→    try {
   138→      const template = await db.quizTemplate.findFirst({
   139→        where: { id: templateId },
   140→      });
   141→      if (!template) {
   142→        return data({ error: "Template not found" }, { status: 404 });
   143→      }
   144→
   145→      await db.quizTemplate.update({
   146→        where: { id: templateId },
   147→        data: { usageCount: { increment: 1 } },
   148→      });
   149→
   150→      const slug = await generateUniqueSlug(session.shop, template.name);
   151→      const quiz = await db.quiz.create({
   152→        data: {
   153→          shop: session.shop,
   154→          title: template.name,
   155→          slug,
   156→          type: "product-recommendation",
   157→          status: "draft",
   158→        },
   159→      });
   160→
   161→      return redirect(`/app/quizzes/${quiz.id}`);
   162→    } catch (error) {
   163→      console.error("use-template action error:", error);
   164→      return data({ error: "Failed to create quiz from template" }, { status: 500 });
   165→    }
   166→  }
   167→
   168→  return data({ error: "Unknown intent" }, { status: 400 });
   169→}
