   110→
   111→export const loader = async ({ request }: LoaderFunctionArgs) => {
   112→  const { session } = await authenticate.admin(request);
   113→
   114→  try {
   115→    const [integrations, sub] = await Promise.all([
   116→      db.emailIntegration.findMany({
   117→        where: { shop: session.shop },
   118→        select: {
   119→          id: true,
   120→          provider: true,
   121→          apiKey: true,
   122→          listId: true,
   123→          isActive: true,
   124→        },
   125→        orderBy: { createdAt: "asc" },
   126→      }),
   127→      db.subscription.findUnique({
   128→        where: { shop: session.shop },
   129→        select: { planId: true },
   130→      }),
   131→    ]);
   132→
   133→    const planId = sub?.planId ?? "free";
   134→
   135→    // Mask API keys for display — keep first 4 and last 4 chars visible
   136→    const masked = integrations.map((i) => ({
   137→      ...i,
   138→      provider: i.provider as Provider,
   139→      apiKey:
   140→        i.apiKey.length > 8
   141→          ? `${i.apiKey.slice(0, 4)}${"•".repeat(Math.max(0, i.apiKey.length - 8))}${i.apiKey.slice(-4)}`
   142→          : "••••••••",
   143→    }));
   144→
   145→    return { integrations: masked as IntegrationRecord[], planId };
   146→  } catch (error) {
   147→    console.error("Integrations loader error:", error);
   148→    throw data({ error: "Failed to load integrations" }, { status: 500 });
   149→  }
