   153→
   154→export const action = async ({ request }: ActionFunctionArgs) => {
   155→  const { session } = await authenticate.admin(request);
   156→  const formData = await request.formData();
   157→  const intent = String(formData.get("intent") ?? "");
   158→  const provider = String(formData.get("provider") ?? "") as Provider;
   159→
   160→  const validProviders: Provider[] = [
   161→    "klaviyo",
   162→    "mailchimp",
   163→    "omnisend",
   164→    "custom-webhook",
   165→  ];
   166→  if (!validProviders.includes(provider)) {
   167→    return data({ error: "Invalid provider" }, { status: 400 });
   168→  }
   169→
   170→  try {
   171→    if (intent === "connect") {
   172→      const apiKey = String(formData.get("apiKey") ?? "").trim();
   173→      const listId = String(formData.get("listId") ?? "").trim() || null;
   174→
   175→      if (!apiKey) {
   176→        return data(
   177→          { error: "API key is required", provider },
   178→          { status: 400 },
   179→        );
   180→      }
   181→
   182→      // Plan gate — check before writing
   183→      const sub = await db.subscription.findUnique({
   184→        where: { shop: session.shop },
   185→        select: { planId: true },
   186→      });
   187→      const planId = sub?.planId ?? "free";
   188→      const config = PROVIDERS.find((p) => p.id === provider);
   189→
   190→      if (!config) {
   191→        return data({ error: "Unknown provider" }, { status: 400 });
   192→      }
   193→
   194→      const planOrder = ["free", "starter", "pro", "enterprise"];
   195→      const currentIdx = planOrder.indexOf(planId);
   196→      const requiredIdx = planOrder.indexOf(config.requiredPlan);
   197→
   198→      if (currentIdx < requiredIdx) {
   199→        return data(
   200→          {
   201→            error: `${config.name} requires the ${config.requiredPlan} plan or higher. Please upgrade.`,
   202→            provider,
   203→          },
   204→          { status: 403 },
   205→        );
   206→      }
   207→
   208→      await db.emailIntegration.upsert({
   209→        where: { shop_provider: { shop: session.shop, provider } },
   210→        create: {
   211→          shop: session.shop,
   212→          provider,
   213→          apiKey,
   214→          listId,
   215→          isActive: true,
   216→        },
   217→        update: { apiKey, listId, isActive: true },
   218→      });
   219→
   220→      const providerName = config.name;
   221→      return {
   222→        success: true,
   223→        message: `${providerName} connected successfully!`,
   224→        provider,
   225→      };
   226→    }
   227→
   228→    if (intent === "disconnect") {
   229→      await db.emailIntegration.deleteMany({
   230→        where: { shop: session.shop, provider },
   231→      });
   232→
   233→      const providerName =
   234→        PROVIDERS.find((p) => p.id === provider)?.name ?? provider;
   235→      return {
   236→        success: true,
   237→        message: `${providerName} disconnected`,
   238→        provider,
   239→      };
   240→    }
   241→
   242→    if (intent === "toggle") {
   243→      const existing = await db.emailIntegration.findUnique({
   244→        where: { shop_provider: { shop: session.shop, provider } },
   245→      });
   246→      if (!existing) {
   247→        return data({ error: "Integration not found" }, { status: 404 });
   248→      }
   249→      await db.emailIntegration.update({
   250→        where: { shop_provider: { shop: session.shop, provider } },
   251→        data: { isActive: !existing.isActive },
   252→      });
   253→      return {
   254→        success: true,
   255→        message: existing.isActive ? "Integration paused" : "Integration enabled",
   256→        provider,
   257→      };
   258→    }
   259→
   260→    return data({ error: "Unknown intent" }, { status: 400 });
   261→  } catch (error) {
   262→    console.error("Integrations action error:", error);
   263→    return data(
   264→      { error: "Action failed. Please try again." },
   265→      { status: 500 },
   266→    );
   267→  }
   268→};
