   105→export const loader = async ({ request }: LoaderFunctionArgs) => {
   106→  const { session } = await authenticate.admin(request);
   107→
   108→  try {
   109→    const startOfMonth = new Date();
   110→    startOfMonth.setDate(1);
   111→    startOfMonth.setHours(0, 0, 0, 0);
   112→
   113→    const [sub, quizCount, responseCount] = await Promise.all([
   114→      db.subscription.findUnique({ where: { shop: session.shop } }),
   115→      db.quiz.count({
   116→        where: { shop: session.shop, status: { not: "archived" } },
   117→      }),
   118→      db.quizResponse.count({
   119→        where: {
   120→          shop: session.shop,
   121→          createdAt: { gte: startOfMonth },
   122→        },
   123→      }),
   124→    ]);
   125→
   126→    return {
   127→      currentPlan: (sub?.planId ?? "free") as PlanId,
   128→      planStatus: sub?.status ?? "active",
   129→      quizCount,
   130→      responseCount,
   131→      trialEndsAt: sub?.trialEndsAt?.toISOString() ?? null,
   132→    };
   133→  } catch (error) {
   134→    console.error("Billing loader error:", error);
   135→    throw data({ error: "Failed to load billing information" }, { status: 500 });
   136→  }
   137→};
   138→
   139→export const action = async ({ request }: ActionFunctionArgs) => {
   140→  const { session } = await authenticate.admin(request);
   141→  const formData = await request.formData();
   142→  const planId = String(formData.get("planId") ?? "") as PlanId;
   143→
   144→  const validPlans: PlanId[] = ["free", "starter", "pro", "enterprise"];
   145→  if (!validPlans.includes(planId)) {
   146→    return data({ error: "Invalid plan selected" }, { status: 400 });
   147→  }
   148→
   149→  try {
   150→    const limits = PLAN_LIMITS[planId];
   151→    await db.subscription.upsert({
   152→      where: { shop: session.shop },
   153→      create: {
   154→        shop: session.shop,
   155→        planId,
   156→        status: "active",
   157→        quizLimit: limits.quizLimit,
   158→        responseLimit: limits.responseLimit,
   159→      },
   160→      update: {
   161→        planId,
   162→        status: "active",
   163→        quizLimit: limits.quizLimit,
   164→        responseLimit: limits.responseLimit,
   165→      },
   166→    });
   167→
   168→    const planName = PLANS.find((p) => p.id === planId)?.name ?? planId;
   169→    const message =
   170→      planId === "free"
   171→        ? "Downgraded to Free plan"
   172→        : `Upgraded to ${planName} plan successfully!`;
   173→
   174→    return { success: true, message };
   175→  } catch (error) {
   176→    console.error("Billing action error:", error);
   177→    return data(
   178→      { error: "Failed to update plan. Please try again." },
   179→      { status: 500 },
   180→    );
   181→  }
   182→};
